<?php if ( ! defined( 'ABSPATH' ) ) { exit; } ?>
<div class="wrap"><h1>Andy Core</h1><h2 class="nav-tab-wrapper"><?php foreach ( YBY_Admin::settings_tabs() as $key => $label ) : ?><a class="nav-tab <?php echo 'system-status' === $key ? 'nav-tab-active' : ''; ?>" href="<?php echo esc_url( add_query_arg( array( 'page' => YBY_Helpers::admin_page_slug(), 'tab' => $key ), admin_url( 'admin.php' ) ) ); ?>"><?php echo esc_html( $label ); ?></a><?php endforeach; ?></h2><table class="widefat striped"><tbody><?php foreach ( $status as $key => $value ) : ?><tr><th><?php echo esc_html( $key ); ?></th><td><?php echo esc_html( is_bool( $value ) ? ( $value ? 'PASS' : 'FAIL' ) : (string) $value ); ?></td></tr><?php endforeach; ?></tbody></table></div>
<p><a class="button" href="<?php echo esc_url( add_query_arg( array( 'page' => YBY_Helpers::admin_page_slug(), 'tab' => 'system-status', 'refresh' => '1' ), admin_url( 'admin.php' ) ) ); ?>"><?php esc_html_e( 'Re-check', 'yby-core' ); ?></a></p>
